CustomField.formula:
IF(ISPICKVAL(Status__c,'ドラフト'), 0,
  IF(ISPICKVAL(Status__c,'申請取消'), 1,
    IF(ISPICKVAL(Status__c,'却下'), 2,
      IF(ISPICKVAL(Status__c,'作成完了'), 3,
        IF(ISPICKVAL(Status__c,'申請中'), 4,
          IF(ISPICKVAL(Status__c,'承認済'), 5,
            IF(ISPICKVAL(Status__c,'クローズ'), 6, 0)
          )
        )
      )
    )
  )
)
